import{_ as e,c as r,o as n,a0 as i}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"no/blog/inner-critic.md","filePath":"no/blog/inner-critic.md"}');const a=e({name:"no/blog/inner-critic.md"},[["render",function(e,t,a,l,s,d){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="a-forsta-den-indre-kritikeren" tabindex="-1">Å forstå den indre kritikeren <a class="header-anchor" href="#a-forsta-den-indre-kritikeren" aria-label="Permalink to &quot;Å forstå den indre kritikeren&quot;">​</a></h1><p>Alle petanquespillere kjenner den stemmen. Den som hvisker «du kommer til å bomme» akkurat idet du skal til å kaste. Den som spiller av ditt siste mislykkede slag i en endeløs løkke. Dette er din indre kritiker – og det å lære å håndtere den er viktig for eliteprestasjoner.</p><h2 id="hva-er-den-indre-kritikeren" tabindex="-1">Hva er den indre kritikeren? <a class="header-anchor" href="#hva-er-den-indre-kritikeren" aria-label="Permalink to &quot;Hva er den indre kritikeren?&quot;">​</a></h2><p>Den indre kritikeren er den indre stemmen som dømmer, kritiserer og undergraver selvtilliten din. I petanque dukker den ofte opp i de verst tenkelige øyeblikk:</p><ul><li><strong>Før et avgjørende skudd</strong>: «Alle ser på. Ikke ødela dette.»</li><li><strong>Etter en bom</strong>: «Du kveles alltid av press.»</li><li><strong>Under en tapsrekke</strong>: «Du er ikke god nok for dette nivået.»</li></ul><p>Denne stemmen prøver ikke å skade deg – den er faktisk et misforstått forsøk på beskyttelse. Hjernen din prøver å forberede deg på å mislykkes, slik at det ikke vil gjøre like vondt. Men denne «beskyttelsen» blir til selvsabotasje.</p><h2 id="a-gjenkjenne-mønstrene-dine" tabindex="-1">Å gjenkjenne mønstrene dine <a class="header-anchor" href="#a-gjenkjenne-mønstrene-dine" aria-label="Permalink to &quot;Å gjenkjenne mønstrene dine&quot;">​</a></h2><p>Det første steget er bevissthet. Begynn å legge merke til når din indre kritiker dukker opp:</p><h3 id="vanlige-utløsere" tabindex="-1">Vanlige utløsere <a class="header-anchor" href="#vanlige-utløsere" aria-label="Permalink to &quot;Vanlige utløsere&quot;">​</a></h3><ul><li>Høypresssituasjoner (kampball, viktige turneringer)</li><li>Etter å ha gjort en feil</li><li>Når motstanderne presterer bra</li><li>Når lagkamerater virker frustrerte</li><li>Fysisk tretthet eller ubehag</li></ul><h3 id="vanlige-meldinger" tabindex="-1">Vanlige meldinger <a class="header-anchor" href="#vanlige-meldinger" aria-label="Permalink to &quot;Vanlige meldinger&quot;">​</a></h3><ul><li>«Du takler ikke press»</li><li>«Du er ikke like god som dem»</li><li>«Alle dømmer deg»</li><li>&quot;Du mislykkes alltid når det gjelder&quot;</li></ul><h2 id="virkningen-pa-ytelsen" tabindex="-1">Virkningen på ytelsen <a class="header-anchor" href="#virkningen-pa-ytelsen" aria-label="Permalink to &quot;Virkningen på ytelsen&quot;">​</a></h2><p>Når den indre kritikeren tar over, reagerer kroppen din:</p><ol><li><strong>Muskelspenningen øker</strong> — Kastet ditt blir stivt</li><li><strong>Pusten blir overfladisk</strong> — Mindre oksygen, mindre fokus</li><li><strong>Synet blir smalere</strong> — Du mister bevisstheten om terrenget</li><li><strong>Beslutningstaking lider</strong> — Du tviler på deg selv</li></ol><p>Dette skaper en ond sirkel: den indre kritikeren forårsaker dårlig prestasjon, noe som gir kritikeren mer ammunisjon.</p><h2 id="strategier-for-a-handtere-den-indre-kritikeren" tabindex="-1">Strategier for å håndtere den indre kritikeren <a class="header-anchor" href="#strategier-for-a-handtere-den-indre-kritikeren" aria-label="Permalink to &quot;Strategier for å håndtere den indre kritikeren&quot;">​</a></h2><h3 id="_1-navngi-det-for-a-temme-det" tabindex="-1">1. Navngi det for å temme det <a class="header-anchor" href="#_1-navngi-det-for-a-temme-det" aria-label="Permalink to &quot;1. Navngi det for å temme det&quot;">​</a></h3><p>Gi din indre kritiker et navn – noe litt latterlig. «Å, der går Negative Nils igjen.» Dette skaper avstand mellom deg og stemmen, noe som gjør den lettere å avfeie.</p><h3 id="_2-utfordre-bevisene" tabindex="-1">2. Utfordre bevisene <a class="header-anchor" href="#_2-utfordre-bevisene" aria-label="Permalink to &quot;2. Utfordre bevisene&quot;">​</a></h3><p>Når kritikeren sier «du bommer alltid under press», spør deg selv: Er det faktisk sant? Kan du tenke på ganger du presterte bra under press? Kritikeren bruker absolutter som sjelden gjenspeiler virkeligheten.</p><h3 id="_3-omformuler-meldingen" tabindex="-1">3. Omformuler meldingen <a class="header-anchor" href="#_3-omformuler-meldingen" aria-label="Permalink to &quot;3. Omformuler meldingen&quot;">​</a></h3><p>Gjør kritikk om til veiledning:</p><ul><li>&quot;Du kommer til å savne&quot; → &quot;Fokuser på rutinen din&quot;</li><li>«Alle ser på» → «Dette er ditt øyeblikk til å skinne»</li><li>&quot;Du kveles alltid&quot; → &quot;Du har håndtert press før&quot;</li></ul><h3 id="_4-bruk-rutinen-din-før-inntak" tabindex="-1">4. Bruk rutinen din før inntak <a class="header-anchor" href="#_4-bruk-rutinen-din-før-inntak" aria-label="Permalink to &quot;4. Bruk rutinen din før inntak&quot;">​</a></h3><p>En solid <a href="/no/utdanning/mental-styrke/rutine-før-inntak">rutine før inntak</a> gir tankene dine noe konstruktivt å fokusere på, og gir mindre rom for kritikeren.</p><h3 id="_5-øv-deg-pa-selvmedfølelse" tabindex="-1">5. Øv deg på selvmedfølelse <a class="header-anchor" href="#_5-øv-deg-pa-selvmedfølelse" aria-label="Permalink to &quot;5. Øv deg på selvmedfølelse&quot;">​</a></h3><p>Behandle deg selv som du ville behandlet en lagkamerat. Ville du sagt til en lagkamerat som sliter «du er forferdelig»? Selvfølgelig ikke. Vis den samme vennlighet til deg selv.</p><h2 id="a-bygge-en-støttende-indre-stemme" tabindex="-1">Å bygge en støttende indre stemme <a class="header-anchor" href="#a-bygge-en-støttende-indre-stemme" aria-label="Permalink to &quot;Å bygge en støttende indre stemme&quot;">​</a></h2><p>Målet er ikke å stilne den indre kritikeren fullstendig – det er nesten umulig. I stedet bør du utvikle en sterkere støttende stemme:</p><h3 id="den-støttende-stemmen-sier" tabindex="-1">Den støttende stemmen sier: <a class="header-anchor" href="#den-støttende-stemmen-sier" aria-label="Permalink to &quot;Den støttende stemmen sier:&quot;">​</a></h3><ul><li>&quot;Ett kast om gangen&quot;</li><li>&quot;Stol på treningen din&quot;</li><li>&quot;Du har gjort dette før&quot;</li><li>&quot;Vær i nuet&quot;</li><li>&quot;Pust og nullstill&quot;</li></ul><h3 id="daglig-praksis" tabindex="-1">Daglig praksis <a class="header-anchor" href="#daglig-praksis" aria-label="Permalink to &quot;Daglig praksis&quot;">​</a></h3><p>Bruk 5 minutter hver dag:</p><ol><li>Husk et øyeblikk da du presterte bra</li><li>Husk hvordan det føltes i kroppen din</li><li>Hør hva din støttende stemme sa</li><li>Forankre denne følelsen med en fysisk gest (berøre kulen din, justere holdningen din)</li></ol><h2 id="i-konkurranse" tabindex="-1">I konkurranse <a class="header-anchor" href="#i-konkurranse" aria-label="Permalink to &quot;I konkurranse&quot;">​</a></h2><p>Når den indre kritikeren dukker opp under en kamp:</p><ol><li><strong>Innrøm det</strong>: «Jeg merker at jeg er selvkritisk»</li><li><strong>Ta et pust</strong>: Sakte, dypt pust for å tilbakestille</li><li><strong>Bruk ankeret ditt</strong>: Den fysiske gesten fra øvelsen din</li><li><strong>Tilbake til rutinen</strong>: Fokuser på prosessen før inntak</li></ol><h2 id="den-langsiktige-reisen" tabindex="-1">Den langsiktige reisen <a class="header-anchor" href="#den-langsiktige-reisen" aria-label="Permalink to &quot;Den langsiktige reisen&quot;">​</a></h2><p>Å håndtere den indre kritikeren er ikke en engangsløsning. Det er en kontinuerlig øvelse som blir lettere med tiden. Elitespillere eliminerer ikke selvtvil – de lærer å prestere til tross for den.</p><p>Den indre kritikeren vil alltid være en del av deg. Men med øvelse blir stemmen dens lavere, og din støttende stemme blir sterkere. Det er den mentale fordelen som skiller gode spillere fra store spillere.</p><hr><p>| <em>Relatert: <a href="/no/utdanning/mental-styrke/håndtering-av-press">Håndtering av press</a> | <a href="/no/utdanning/mental-styrke/rutine-før-skudd">Rutine før skudd</a> | <a href="/no/utdanning/mindfulness/teknikker">Mindfulness-teknikker</a></em> |</p>',43)])])}]]);export{t as __pageData,a as default};
